syntax:
Template instantiation occurs at the point of use, with specializations and exception specifications instantiated as needed:

// General template
template<typename T>
class X { /* ... */ };

// Explicit specialization
template<>
class X<int> { /* ... */ };

// Function template
template<typename T>
void f(T t) { /* ... */ };

// Instantiation occurs when the template is used in code, e.g., f<int>(value);

code_example:
#include <iostream>

template<typename T>
class X {
public:
    void display() { std::cout << "Generic template" << std::endl; }
};

// Specialization for int
template<>
class X<int> {
public:
    void display() { std::cout << "Specialized template for int" << std::endl; }
};

int main() {
    X<double> x1; // Instantiates generic template for T=double
    x1.display();
    X<int> x2; // Instantiates specialized template for int
    x2.display();
    return 0;
}
